package pe.com.dentalamericana.finance;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import pe.com.dentalamericana.treatment.TreatmentPlan;
@Service public class ReceivableAccountService{private final ReceivableAccountRepository accounts;public ReceivableAccountService(ReceivableAccountRepository accounts){this.accounts=accounts;}@Transactional public ReceivableAccount ensureFor(TreatmentPlan plan){return accounts.findByPlanId(plan.getId()).map(a->{a.updateTotal(plan.getTotal());return a;}).orElseGet(()->accounts.save(new ReceivableAccount(plan.getId(),plan.getPatientId(),plan.getTotal())));}}
